def solve(inputs: dict) -> float:
    def get(*names):
        for name in names:
            if name in inputs:
                return inputs[name]
        raise KeyError(names)
    M = get('M', 'matrix', 'mat')
    power = int(get('power', 'exponent', 'p', 'n'))
    mod = int(get('modulus', 'mod', 'm'))
    base = [[int(M[0][0]) % mod, int(M[0][1]) % mod],
            [int(M[1][0]) % mod, int(M[1][1]) % mod]]
    result = [[1, 0], [0, 1]]
    def mul(a, b):
        return [[(a[0][0]*b[0][0] + a[0][1]*b[1][0]) % mod,
                 (a[0][0]*b[0][1] + a[0][1]*b[1][1]) % mod],
                [(a[1][0]*b[0][0] + a[1][1]*b[1][0]) % mod,
                 (a[1][0]*b[0][1] + a[1][1]*b[1][1]) % mod]]
    while power:
        if power & 1:
            result = mul(result, base)
        base = mul(base, base)
        power >>= 1
    return float(sum(map(sum, result)))

